3	import { createContext, useCallback, useContext, useMemo, useState, type ReactNode } from "react";
4	import { LOCALE_COOKIE, LOCALE_PARAM, type Locale } from "./config";
5	import { MESSAGES, type Messages } from "./messages";
6	
7	interface I18nState {
8	  locale: Locale;
9	  setLocale: (next: Locale) => void;
10	}
11	
12	const Ctx = createContext<I18nState | null>(null);
13	
14	/** Holds the page language. The server picks the first one, so the page never flashes English. */
15	export function I18nProvider({ initialLocale, children }: { initialLocale: Locale; children: ReactNode }) {
16	  const [locale, setLocaleState] = useState<Locale>(initialLocale);
17	
18	  const setLocale = useCallback((next: Locale) => {
19	    setLocaleState(next);
20	    document.documentElement.lang = next;
21	    document.cookie = `${LOCALE_COOKIE}=${next}; path=/; max-age=${60 * 60 * 24 * 365}; samesite=lax`;
22	    // A ?lang= in the address would override the new choice on reload, so drop it.
23	    const url = new URL(window.location.href);
24	    if (url.searchParams.has(LOCALE_PARAM)) {
25	      url.searchParams.delete(LOCALE_PARAM);
26	      window.history.replaceState(window.history.state, "", url);
27	    }
28	  }, []);
29	
30	  const value = useMemo(() => ({ locale, setLocale }), [locale, setLocale]);
31	  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
32	}
33	
34	export function useLocale(): I18nState {
35	  const v = useContext(Ctx);
36	  if (!v) throw new Error("useLocale must be used inside <I18nProvider>");
37	  return v;
38	}
