40	/** The current language's words for one area of the site, e.g. `const t = useT("home"); t.hero.title`. */
41	export function useT<N extends keyof Messages>(namespace: N): Messages[N] {
42	  const { locale } = useLocale();
43	  return MESSAGES[locale][namespace];
44	}
