121	import {
122	  createPcmWorkletUrl,
123	  preferredTimeBase,
124	  TranscriptionSession,
125	  type CaptionSettings,
126	  type CaptionState,
127	  type TranscriptionStatus,
128	} from "@heard/shared";
129	import {
130	  CaptionsIcon,
131	  CaptionText,
132	  ExternalIcon,
133	  PanelIcon,
134	  PlayIcon,
135	  StatusBadge,
136	  StopIcon,
137	  TranscriptToolbar,
