142	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
143	import { DeepgramKeyDialog } from "@/components/DeepgramKeyDialog";
144	import { DeepgramKeySettings } from "@/components/DeepgramKeySettings";
145	import { SettingsPopover } from "@/components/SettingsPopover";
146	import { StartGuide } from "@/components/StartGuide";
147	import { captureTabAudio, detectCaptureSupport } from "@/lib/capture";
148	import { createGetToken, keyMode, TOKEN_ENDPOINT_PATH, useServerKeyStatus, useUserDeepgramKey } from "@/lib/deepgram-key";
149	import { resolveVideo, type PlayerAdapter, type PlayerError, type PlayerState } from "@/lib/providers";
150	import { migrateLegacyStorage } from "@/lib/legacy-storage";
151	import { loadCaptionSettings, saveCaptionSettings } from "@/lib/settings-storage";
152	
153	const GUIDE_KEY = "heard:skip-start-guide";
154	const POLL_MS = 250;
155	
156	let workletUrl: string | null = null;
157	/** One Blob URL per page load is enough for every session. */
158	function getWorkletUrl() {
159	  return (workletUrl ??= createPcmWorkletUrl());
160	}
161	
162	const RUNNING: TranscriptionStatus[] = ["connecting", "live", "paused", "reconnecting"];
163	
164	export function WatchExperience({ url }: { url: string }) {
165	  const resolved = useMemo(() => resolveVideo(url), [url]);
166	  if (!resolved.ok) throw new Error(resolved.message); // WatchShell only renders us for valid links
167	  const { provider, video } = resolved;
168	
169	  const hostRef = useRef<HTMLDivElement>(null);
170	  const stageRef = useRef<HTMLDivElement>(null);
171	  const adapterRef = useRef<PlayerAdapter | null>(null);
172	
173	  const [session] = useState(
174	    () =>
175	      new TranscriptionSession({
176	        // The user's own Deepgram key when saved, else a server-minted JWT.
177	        // Absolute URL: the shared fetcher builds error messages with `new URL(endpoint)`.
178	        getToken: createGetToken(`${window.location.origin}${TOKEN_ENDPOINT_PATH}`),
179	        workletUrl: getWorkletUrl(),
180	        getMediaTime: () => adapterRef.current?.getCurrentTime() ?? null,
181	        preservePlayback: false,
182	      }),
183	  );
184	  const ts = useTranscriptionSession(session);
185	  const running = RUNNING.includes(ts.status);
186	
187	  const [playerReady, setPlayerReady] = useState(false);
188	  const [playerError, setPlayerError] = useState<PlayerError | null>(null);
189	  const [title, setTitle] = useState<string | null>(null);
190	  const [isLive, setIsLive] = useState(video.maybeLive);
191	  const [currentTime, setCurrentTime] = useState(0);
192	
193	  const [settings, setSettingsState] = useState<CaptionSettings>(loadCaptionSettings);
194	  const setSettings = useCallback((next: CaptionSettings) => {
195	    setSettingsState(next);
196	    saveCaptionSettings(next);
197	  }, []);
198	  // Language changes apply live: a new spoken language reconnects, a new caption language translates.
199	  useEffect(() => session.setLanguages(settings.spokenLanguage, settings.captionLanguage), [session, settings.spokenLanguage, settings.captionLanguage]);
200	  const captionTranslation = ts.translation.target ? ts.translation.caption : null;
201	  const overlayAllowed = provider.capabilities.allowsCaptionOverlay;
202	  const placement = overlayAllowed ? settings.position : "below";
203	
204	  const [support] = useState(detectCaptureSupport);
205	  const [guideOpen, setGuideOpen] = useState(false);
206	  const [skipGuide, setSkipGuide] = useState(() => readFlag(GUIDE_KEY));
207	  const [captureError, setCaptureError] = useState<string | null>(null);
208	  const [requesting, setRequesting] = useState(false);
209	
210	  const [panelOpen, setPanelOpen] = useState(true);
211	  const [query, setQuery] = useState("");
212	  const [fullscreen, setFullscreen] = useState(false);
213	  const [settingsOpen, setSettingsOpen] = useState(false);
214	  /** Settings were opened to fix the Deepgram key: scroll there and show the form. */
215	  const [keyFocus, setKeyFocus] = useState(false);
216	
217	  const userKey = useUserDeepgramKey();
218	  const [serverKey, setServerKey] = useServerKeyStatus();
219	  const mode = keyMode(userKey, serverKey);
220	  const [keyDialogOpen, setKeyDialogOpen] = useState(false);
221	
222	  /* ----------------------------- player ----------------------------- */
223	
224	  const applyPlayerState = useCallback(
225	    (state: PlayerState) => {
226	      // Only send audio while the video is actually playing (buffering is a short blip).
227	      session.setPaused(!(state === "playing" || state === "buffering"));
228	    },
229	    [session],
230	  );
231	
232	  useEffect(() => {
233	    const host = hostRef.current;
234	    if (!host) return;
235	    let cancelled = false;
236	    let adapter: PlayerAdapter | null = null;
237	    provider
238	      .mount(host, video, {
239	        onReady: () => {
240	          if (cancelled) return;
241	          setPlayerReady(true);
242	          setTitle(adapterRef.current?.getTitle() ?? null);
243	        },
244	        onStateChange: (state) => {
245	          if (cancelled) return;
246	          applyPlayerState(state);
247	          const a = adapterRef.current;
248	          if (a) {
249	            setIsLive(a.isLive());
250	            setTitle((t) => a.getTitle() ?? t);
251	          }
252	        },
253	        onError: (err) => !cancelled && setPlayerError(err),
254	      })
255	      .then((a) => {
256	        if (cancelled) return a.destroy();
257	        adapter = a;
258	        adapterRef.current = a;
259	      })
260	      .catch((err: Error) => {
261	        if (!cancelled) setPlayerError({ code: "load", message: err.message, embeddingBlocked: false });
262	      });
263	    return () => {
264	      cancelled = true;
265	      adapter?.destroy();
266	      if (adapterRef.current === adapter) adapterRef.current = null;
267	    };
268	  }, [provider, video, applyPlayerState]);
269	
270	  // Poll the playhead: drives the active transcript line and detects seeks.
271	  useEffect(() => {
272	    let prev: { t: number; at: number; state: PlayerState } | null = null;
273	    let ticks = 0;
274	    const id = setInterval(() => {
275	      const a = adapterRef.current;
276	      if (!a) return;
277	      const t = a.getCurrentTime();
278	      const at = performance.now();
279	      const state = a.getState();
280	      if (prev) {
281	        const elapsed = (at - prev.at) / 1000;
282	        const expected = prev.state === "playing" ? prev.t + elapsed * a.getPlaybackRate() : prev.t;
283	        const tolerance = 1.25 + elapsed * 0.25;
284	        if (Math.abs(t - expected) > tolerance) session.markDiscontinuity();
285	      }
286	      prev = { t, at, state };
287	      setCurrentTime((c) => (Math.abs(c - t) >= 0.2 ? t : c));
288	      if (++ticks % 8 === 0) {
289	        // Title / live flag can arrive late (e.g. once a livestream starts playing).
290	        setIsLive(a.isLive());
291	        setTitle((old) => a.getTitle() ?? old);
292	      }
293	    }, POLL_MS);
294	    return () => clearInterval(id);
295	  }, [session]);
296	
297	  /* ---------------------------- session ---------------------------- */
298	
299	  // Stop capturing when leaving the page or switching videos (this component is keyed by video).
300	  useEffect(() => {
301	    const onHide = () => void session.stop();
302	    window.addEventListener("pagehide", onHide);
303	    return () => {
304	      window.removeEventListener("pagehide", onHide);
305	      void session.stop();
306	    };
307	  }, [session]);
308	
309	  const startCapture = useCallback(async () => {
310	    setCaptureError(null);
311	    setRequesting(true);
312	    let stream: MediaStream;
313	    try {
314	      stream = await captureTabAudio();
315	    } catch (err) {
316	      setRequesting(false);
317	      setCaptureError((err as Error).message);
318	      setGuideOpen(true);
319	      return;
320	    }
321	    setRequesting(false);
322	    setGuideOpen(false);
323	    await session.start(stream);
324	    const a = adapterRef.current;
325	    if (a) {
326	      const state = a.getState();
327	      if (state !== "playing" && state !== "buffering") a.play();
328	      applyPlayerState(a.getState());
329	    }
330	  }, [session, applyPlayerState]);
331	
332	  const onStartClick = () => {
333	    if (!support.ok) return;
334	    if (mode === "none") {
335	      // No server key and no key of their own yet: ask for one first.
336	      setCaptureError(null);
337	      setKeyDialogOpen(true);
338	      return;
339	    }
340	    // Calling getDisplayMedia straight from the click keeps Chrome's user-activation requirement.
341	    if (skipGuide) void startCapture();
342	    else {
343	      setCaptureError(null);
344	      setGuideOpen(true);
345	    }
346	  };
347	
348	  // Verifying the key used up the click's user activation, so getDisplayMedia must come from
349	  // a fresh click: always continue through the start guide's "Choose this tab" button.
350	  const onKeySaved = useCallback(() => {
351	    setKeyDialogOpen(false);
352	    setCaptureError(null);
353	    setGuideOpen(true);
354	  }, []);
355	  const closeKeyDialog = useCallback(() => setKeyDialogOpen(false), []);
356	
357	  const onSettingsOpenChange = useCallback((open: boolean) => {
358	    setSettingsOpen(open);
359	    if (!open) setKeyFocus(false);
360	  }, []);
361	
362	  const openKeySettings = () => {
363	    setKeyFocus(true);
364	    setSettingsOpen(true);
365	  };
366	
367	  const onSkipGuideChange = (v: boolean) => {
368	    setSkipGuide(v);
369	    writeFlag(GUIDE_KEY, v);
370	  };
371	
372	  /* --------------------------- fullscreen --------------------------- */
373	
374	  useEffect(() => {
375	    const onChange = () => setFullscreen(document.fullscreenElement === stageRef.current);
376	    document.addEventListener("fullscreenchange", onChange);
377	    return () => document.removeEventListener("fullscreenchange", onChange);
378	  }, []);
379	
380	  const toggleFullscreen = useCallback(() => {
381	    if (document.fullscreenElement) void document.exitFullscreen();
382	    else void stageRef.current?.requestFullscreen().catch(() => undefined);
383	  }, []);
384	
385	  /* ---------------------------- keyboard ---------------------------- */
386	
387	  const settingsRef = useRef(settings);
388	  settingsRef.current = settings;
389	  useEffect(() => {
390	    const onKey = (e: KeyboardEvent) => {
391	      if (e.metaKey || e.ctrlKey || e.altKey || e.defaultPrevented) return;
392	      const el = e.target as HTMLElement | null;
393	      if (el && (el.isContentEditable || ["INPUT", "TEXTAREA", "SELECT"].includes(el.tagName))) return;
394	      if (e.key === "c" || e.key === "C") {
395	        e.preventDefault();
396	        setSettings({ ...settingsRef.current, enabled: !settingsRef.current.enabled });
397	      } else if (e.key === "f" || e.key === "F") {
398	        e.preventDefault();
399	        toggleFullscreen();
400	      }
401	    };
402	    window.addEventListener("keydown", onKey);
403	    return () => window.removeEventListener("keydown", onKey);
404	  }, [setSettings, toggleFullscreen]);
405	
406	  /* ---------------------------- transcript ---------------------------- */
407	
408	  const timeBase = preferredTimeBase(ts.lines);
409	  const onSeek = useCallback((s: number) => adapterRef.current?.seekTo(s), []);
410	  const fileName = title ?? "heard-transcript";
411	
412	  const sessionError = ts.status === "error" ? ts.error : null;
413	  const reconnecting = ts.status === "reconnecting";
414	  const keyError = Boolean(sessionError && /API key/i.test(sessionError));
415	  const noServerKeyError = Boolean(sessionError && /doesn.t provide a Deepgram API key/i.test(sessionError));
416	
417	  // The token endpoint said this server has no key (e.g. the status check failed earlier).
418	  useEffect(() => {
419	    if (noServerKeyError && serverKey !== false) setServerKey(false);
420	  }, [noServerKeyError, serverKey, setServerKey]);
421	
422	  /* ------------------------------ render ------------------------------ */
423	
424	  const iconBtn =
425	    "inline-flex h-10 w-10 items-center justify-center rounded-xl text-ink-300 transition-colors hover:bg-ink-800 hover:text-ink-100 aria-pressed:text-accent disabled:opacity-40";
426	
427	  const captionHint = playerError ? null : hintFor(ts.status, support.ok);
428	
429	  return (
430	    <div
431	      className={`mx-auto grid w-full max-w-[1600px] flex-1 gap-0 lg:gap-6 lg:px-6 lg:py-5 ${
432	        panelOpen ? "lg:grid-cols-[minmax(0,1fr)_400px]" : "lg:grid-cols-[minmax(0,1fr)]"
433	      }`}
434	    >
435	      {/* Stage: player + caption bar + controls. This is what goes fullscreen. */}
436	      <section aria-label="Video" className="min-w-0">
437	        <div ref={stageRef} className={`stage relative flex flex-col bg-ink-950 ${fullscreen && settingsOpen ? "pr-80" : ""}`}>
438	          <div className="stage-player relative aspect-video max-h-[calc(100dvh-15rem)] min-h-[200px] w-full min-w-[200px] overflow-hidden bg-black lg:rounded-t-2xl">
439	            <div ref={hostRef} className={`absolute inset-0 ${playerError ? "hidden" : ""}`} />
440	            {!playerReady && !playerError && <div className="absolute inset-0 animate-pulse bg-ink-900" aria-hidden="true" />}
441	            {playerError && <PlayerErrorPanel error={playerError} canonicalUrl={video.canonicalUrl} providerName={provider.name} />}
442	            {placement === "overlay" && settings.enabled && (
443	              <CaptionText caption={ts.caption} settings={settings} translation={captionTranslation} className="absolute inset-x-4 bottom-[8%]" />
444	            )}
445	          </div>
446	
447	          {placement === "below" && settings.enabled && <CaptionBar caption={ts.caption} settings={settings} translation={captionTranslation} hint={captionHint} />}
448	
449	          {/* Controls */}
450	          <div className={`flex flex-wrap items-center gap-2 border-ink-800 bg-ink-900 px-3 py-2.5 sm:px-4 ${fullscreen ? "" : "lg:rounded-b-2xl lg:border-x lg:border-b"}`}>
451	            {running ? (
452	              <button
453	                type="button"
454	                onClick={() => void session.stop()}
455	                className="inline-flex h-10 items-center gap-2 rounded-xl bg-ink-700 px-4 text-sm font-semibold text-ink-100 transition-colors hover:bg-ink-600"
456	              >
457	                <StopIcon size={14} /> Stop captions
458	              </button>
459	            ) : (
460	              <button
461	                type="button"
462	                onClick={onStartClick}
463	                disabled={!support.ok || requesting || Boolean(playerError)}
464	                className="inline-flex h-10 items-center gap-2 rounded-xl bg-accent px-4 text-sm font-semibold text-accent-ink transition-colors hover:bg-accent-strong disabled:cursor-not-allowed disabled:opacity-50"
465	              >
466	                <PlayIcon size={14} /> {requesting ? "Waiting for Chrome…" : "Start captions"}
467	              </button>
468	            )}
469	            <StatusBadge status={ts.status} />
470	            {isLive && (
471	              <span className="hidden items-center rounded-full bg-ink-800 px-2.5 py-1 text-xs font-medium text-ink-300 ring-1 ring-ink-700 sm:inline-flex">
472	                Livestream
473	              </span>
474	            )}
475	            <p className="hidden min-w-0 flex-1 truncate px-1 text-sm text-ink-400 md:block" title={title ?? undefined}>
476	              {title}
477	            </p>
478	
479	            <div className="ml-auto flex items-center gap-0.5">
480	              <button
481	                type="button"
482	                className={iconBtn}
483	                onClick={() => setSettings({ ...settings, enabled: !settings.enabled })}
484	                aria-pressed={settings.enabled}
485	                aria-label="Show captions"
486	                title="Show captions (c)"
487	              >
488	                <CaptionsIcon size={20} />
489	              </button>
490	              <SettingsPopover
491	                settings={settings}
492	                onChange={setSettings}
493	                showPosition={overlayAllowed}
494	                buttonClassName={iconBtn}
495	                sheet={fullscreen}
496	                open={settingsOpen}
497	                onOpenChange={onSettingsOpenChange}
498	                scrollToChildren={keyFocus}
499	              >
500	                <DeepgramKeySettings userKey={userKey} serverKey={serverKey} initiallyEditing={keyFocus} running={running} />
501	              </SettingsPopover>
502	              {!fullscreen && (
503	                <button
504	                  type="button"
505	                  className={iconBtn}
506	                  onClick={() => setPanelOpen((o) => !o)}
507	                  aria-pressed={panelOpen}
508	                  aria-label="Transcript panel"
509	                  title={panelOpen ? "Hide transcript" : "Show transcript"}
510	                >
511	                  <PanelIcon size={18} />
512	                </button>
513	              )}
514	              <button
515	                type="button"
516	                className={iconBtn}
517	                onClick={toggleFullscreen}
518	                aria-label={fullscreen ? "Exit full screen" : "Full screen"}
519	                title={fullscreen ? "Exit full screen (f)" : "Full screen (f)"}
520	              >
521	                <FullscreenIcon exit={fullscreen} />
522	              </button>
523	            </div>
524	          </div>
525	
526	          {guideOpen && (
527	            <StartGuide
528	              onShare={() => void startCapture()}
529	              onClose={() => setGuideOpen(false)}
530	              busy={requesting}
531	              error={captureError}
532	              skipNextTime={skipGuide}
533	              onSkipNextTimeChange={onSkipGuideChange}
534	            />
535	          )}
536	          {keyDialogOpen && <DeepgramKeyDialog onSaved={onKeySaved} onClose={closeKeyDialog} />}
537	        </div>
538	
539	        {/* Notices */}
540	        <div className="space-y-2 px-3 pt-3 empty:hidden sm:px-4 lg:px-0" aria-live="polite">
541	          {!support.ok && <Banner tone="info">{support.reason}</Banner>}
542	          {captureError && !guideOpen && (
543	            <Banner tone="error" action={{ label: "Try again", onClick: () => void startCapture() }}>
544	              {captureError}
545	            </Banner>
546	          )}
547	          {sessionError && (
548	            <Banner
549	              tone="error"
550	              action={
551	                keyError
552	                  ? mode === "none"
553	                    ? { label: "Add your Deepgram key", onClick: () => (support.ok ? setKeyDialogOpen(true) : openKeySettings()) }
554	                    : { label: "Check Deepgram key", onClick: openKeySettings }
555	                  : support.ok
556	                    ? { label: "Restart captions", onClick: () => void startCapture() }
557	                    : undefined
558	              }
559	              secondary={keyError && support.ok && mode !== "none" ? { label: "Restart captions", onClick: onStartClick } : undefined}
560	            >
561	              Captions stopped: {sessionError}
562	            </Banner>
563	          )}
564	          {reconnecting && <Banner tone="info">Reconnecting to Deepgram… {ts.error ? `(${ts.error})` : ""} Audio is buffered meanwhile.</Banner>}
565	        </div>
566	      </section>
567	
568	      {/* Transcript */}
569	      {panelOpen && (
570	        <aside
571	          aria-label="Transcript"
